-- ZORO BACKEND SETUP — NEW, EMPTY SUPABASE PROJECTS ONLY
-- Generated by npm run setup. Do not edit this combined file.
-- Run the whole file once; public registration is enabled by the later sections.

-- SECTION: schema.sql
-- Run once in a NEW Supabase project's SQL editor. No secrets belong here.
begin;
create schema if not exists kora_private;
revoke all on schema kora_private from public, anon, authenticated;
create table kora_private.allowed_emails(email text primary key check(email=lower(email)));
alter table kora_private.allowed_emails enable row level security;
-- Add approved emails with the separate invite.sql example.

create function public.kora_allowed() returns boolean
language sql stable security definer set search_path = '' as $$
  select exists(select 1 from auth.users u join kora_private.allowed_emails a
    on a.email=lower(u.email) where u.id=(select auth.uid()) and u.email_confirmed_at is not null);
$$;
revoke all on function public.kora_allowed() from public, anon;
grant execute on function public.kora_allowed() to authenticated;

create table public.kora_vaults (
  user_id uuid primary key references auth.users(id) on delete cascade,
  payload jsonb not null,
  revision bigint not null default 1,
  updated_at timestamptz not null default now()
);
alter table public.kora_vaults enable row level security;
revoke all on public.kora_vaults from public, anon, authenticated;
grant select on public.kora_vaults to authenticated;
create policy "Owner reads approved private vault" on public.kora_vaults for select to authenticated
using(user_id=(select auth.uid()) and (select public.kora_allowed()));

-- A compare-and-swap write prevents lost updates across PC and phone.
-- No client-selected user ID, no anonymous access, no direct writes.
create function public.save_kora_vault(expected_revision bigint,new_payload jsonb)
returns bigint language plpgsql security definer set search_path = '' as $$
declare actor uuid := auth.uid(); next_revision bigint;
begin
  if actor is null or not public.kora_allowed() then raise exception 'Access denied'; end if;
  if expected_revision < 0 or expected_revision is null then raise exception 'Invalid revision'; end if;
  if new_payload is null or jsonb_typeof(new_payload) <> 'object'
     or octet_length(new_payload::text)>2097152
     or jsonb_typeof(new_payload->'accounts') is distinct from 'array'
     or jsonb_typeof(new_payload->'entries') is distinct from 'array'
     or jsonb_typeof(new_payload->'receipts') is distinct from 'array'
     or jsonb_typeof(new_payload->'debts') is distinct from 'array'
  then raise exception 'Invalid record format'; end if;
  if expected_revision=0 then
    insert into public.kora_vaults(user_id,payload,revision) values(actor,new_payload,1)
    on conflict do nothing returning revision into next_revision;
  else
    update public.kora_vaults set payload=new_payload,revision=revision+1,updated_at=now()
    where user_id=actor and revision=expected_revision returning revision into next_revision;
  end if;
  if next_revision is null then raise exception 'Sync conflict'; end if;
  return next_revision;
end;
$$;
revoke all on function public.save_kora_vault(bigint,jsonb) from public, anon;
grant execute on function public.save_kora_vault(bigint,jsonb) to authenticated;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('kora-receipts','kora-receipts',false,2097152,array['image/jpeg']);
create policy "Owner reads receipt" on storage.objects for select to authenticated
using(bucket_id='kora-receipts' and (storage.foldername(name))[1]=(select auth.uid())::text and (select public.kora_allowed()));
create policy "Owner uploads receipt" on storage.objects for insert to authenticated
with check(bucket_id='kora-receipts' and (storage.foldername(name))[1]=(select auth.uid())::text and (select public.kora_allowed()));
create policy "Owner removes receipt" on storage.objects for delete to authenticated
using(bucket_id='kora-receipts' and (storage.foldername(name))[1]=(select auth.uid())::text and (select public.kora_allowed()));
commit;

-- SECTION: access-hardening.sql
-- Apply after schema.sql, then enable public.kora_before_signup as the
-- Before User Created hook in Supabase Authentication.
begin;
create or replace function public.kora_invited() returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from auth.users u join kora_private.allowed_emails a
    on a.email = lower(u.email)
    where u.id = (select auth.uid()) and u.email_confirmed_at is not null
  );
$$;
revoke all on function public.kora_invited() from public, anon;
grant execute on function public.kora_invited() to authenticated;

create or replace function public.kora_allowed() returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select auth.jwt()->>'aal') = 'aal2', false)
    and public.kora_invited();
$$;
revoke all on function public.kora_allowed() from public, anon;
grant execute on function public.kora_allowed() to authenticated;

create or replace function public.kora_before_signup(event jsonb) returns jsonb
language sql stable security definer set search_path = '' as $$
  select case when exists (
    select 1 from kora_private.allowed_emails
    where email = lower(event->'user'->>'email')
  ) then '{}'::jsonb
  else '{"error":{"http_code":403,"message":"Registration requires an invitation."}}'::jsonb end;
$$;
revoke all on function public.kora_before_signup(jsonb) from public, anon, authenticated;
grant execute on function public.kora_before_signup(jsonb) to supabase_auth_admin;
commit;

-- SECTION: session-security.sql
-- Run after access-hardening.sql.
begin;
create or replace function public.kora_allowed() returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select auth.jwt()->>'aal') = 'aal2', false)
    and public.kora_invited()
    and exists (
      select 1 from auth.sessions s where s.user_id = (select auth.uid())
      and s.id::text = (select auth.jwt()->>'session_id')
      and (s.not_after is null or s.not_after > now())
    );
$$;

create or replace function public.kora_sessions()
returns table (started_at timestamptz, last_refresh timestamptz, browser_agent text, is_current boolean)
language sql stable security definer set search_path = '' as $$
  select s.created_at, s.refreshed_at, left(s.user_agent, 240),
         s.id::text = (select auth.jwt()->>'session_id')
  from auth.sessions s
  where public.kora_allowed() and s.user_id = (select auth.uid())
    and (s.not_after is null or s.not_after > now())
    and s.aal::text = 'aal2'
  order by s.created_at desc;
$$;
revoke all on function public.kora_sessions() from public, anon;
grant execute on function public.kora_sessions() to authenticated;
commit;

-- SECTION: public-registration.sql
-- Apply after session-security.sql. The historical function name is retained
-- for compatibility with builds that already call it.
begin;
create or replace function public.kora_invited() returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from auth.users u
    where u.id = (select auth.uid())
      and u.email is not null and u.email_confirmed_at is not null
  );
$$;

-- Remove the invitation check even before the dashboard hook is disabled.
create or replace function public.kora_before_signup(event jsonb) returns jsonb
language sql stable security definer set search_path = '' as $$
  select '{}'::jsonb;
$$;
commit;

-- SECTION: delete-account.sql
-- Self-service account removal. Receipt objects must be removed through
-- Storage's API before deleting the Auth identity.
create or replace function public.zoro_delete_own_account() returns void
language plpgsql security definer set search_path = '' as $$
declare actor uuid := auth.uid();
begin
  if actor is null or not public.kora_allowed() then
    raise exception 'Verified sign-in required';
  end if;
  if exists (
    select 1 from storage.objects
    where bucket_id = 'kora-receipts'
      and (storage.foldername(name))[1] = actor::text
  ) then
    raise exception 'Remove receipt objects before deleting this account';
  end if;
  delete from auth.users where id = actor;
end;
$$;
revoke all on function public.zoro_delete_own_account() from public, anon;
grant execute on function public.zoro_delete_own_account() to authenticated;

-- SECTION: backend-links.sql
-- Remembers a user-owned project's public connection settings with the Zoro ID.
create table if not exists public.zoro_backend_links (
  user_id uuid primary key references auth.users(id) on delete cascade,
  project_url text not null check (project_url ~ '^https://[a-z0-9]{10,40}\.supabase\.co$'),
  publishable_key text not null check (publishable_key ~ '^sb_publishable_[A-Za-z0-9_-]{10,180}$'),
  updated_at timestamptz not null default now()
);
alter table public.zoro_backend_links enable row level security;
revoke all on public.zoro_backend_links from anon, authenticated;
grant select on public.zoro_backend_links to authenticated;
create policy "Owner reads backend link" on public.zoro_backend_links
  for select to authenticated using (user_id = auth.uid() and public.kora_allowed());
create or replace function public.zoro_save_backend_link(project_url text, publishable_key text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not public.kora_allowed() then raise exception 'Verified sign-in required'; end if;
  insert into public.zoro_backend_links(user_id, project_url, publishable_key)
  values(auth.uid(), project_url, publishable_key)
  on conflict(user_id) do update set project_url=excluded.project_url,
    publishable_key=excluded.publishable_key, updated_at=now();
end; $$;
create or replace function public.zoro_clear_backend_link() returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not public.kora_allowed() then raise exception 'Verified sign-in required'; end if;
  delete from public.zoro_backend_links where user_id = auth.uid();
end; $$;
revoke all on function public.zoro_save_backend_link(text,text), public.zoro_clear_backend_link() from public, anon;
grant execute on function public.zoro_save_backend_link(text,text), public.zoro_clear_backend_link() to authenticated;

-- SECTION: phone-auth.sql
-- Optional phone sign-in still requires TOTP and a valid session before wallet access.
create or replace function public.kora_invited() returns boolean
language sql stable security definer set search_path = '' as $$
  select exists(select 1 from auth.users u where u.id=(select auth.uid())
    and ((u.email is not null and u.email_confirmed_at is not null)
      or (u.phone is not null and u.phone_confirmed_at is not null)));
$$;

-- SECTION: device-approval.sql
-- Optional per-user new-browser approval. Run after session-security/public-registration.
begin;
create table if not exists public.zoro_device_preferences (
  user_id uuid primary key references auth.users(id) on delete cascade,
  approval_required boolean not null default false
);
create table if not exists public.zoro_devices (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  session_id text not null,
  token_hash text not null,
  label text not null,
  reported_location text not null default 'Unavailable',
  status text not null check(status in ('pending','approved','rejected')),
  requested_at timestamptz not null default now(),
  last_seen timestamptz not null default now(),
  unique(user_id,session_id)
);
alter table public.zoro_device_preferences enable row level security;
alter table public.zoro_devices enable row level security;
revoke all on public.zoro_device_preferences, public.zoro_devices from public,anon,authenticated;
create or replace function public.zoro_base_allowed() returns boolean
language sql stable security definer set search_path='' as $$
  select coalesce((select auth.jwt()->>'aal')='aal2',false) and public.kora_invited()
    and exists(select 1 from auth.sessions s where s.user_id=(select auth.uid())
      and s.id::text=(select auth.jwt()->>'session_id') and (s.not_after is null or s.not_after>now()));
$$;
create or replace function public.kora_allowed() returns boolean
language sql stable security definer set search_path='' as $$
  select public.zoro_base_allowed() and (
    not exists(select 1 from public.zoro_device_preferences p where p.user_id=(select auth.uid()) and p.approval_required)
    or exists(select 1 from public.zoro_devices d where d.user_id=(select auth.uid())
      and d.session_id=(select auth.jwt()->>'session_id') and d.status='approved')
  );
$$;
create or replace function public.zoro_device_gate(device_token text, device_label text, location_label text default 'Unavailable') returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid(); sid text:=auth.jwt()->>'session_id'; hashed text; required boolean; device public.zoro_devices;
begin
  if not public.zoro_base_allowed() then raise exception 'Verified authenticator sign-in required'; end if;
  if device_token !~ '^[a-f0-9]{64}$' or device_token is null then raise exception 'Invalid device token'; end if;
  perform pg_advisory_xact_lock(hashtextextended(actor::text,0));
  hashed:=encode(sha256(convert_to(device_token,'UTF8')),'hex');
  select coalesce((select p.approval_required from public.zoro_device_preferences p where p.user_id=actor),false) into required;
  select * into device from public.zoro_devices where user_id=actor and session_id=sid;
  if device.id is null then
    insert into public.zoro_devices(user_id,session_id,token_hash,label,reported_location,status)
    values(actor,sid,hashed,left(coalesce(device_label,'Browser'),120),left(coalesce(location_label,'Unavailable'),160),
      case when not required or exists(select 1 from public.zoro_devices where user_id=actor and token_hash=hashed and status='approved') then 'approved' else 'pending' end)
    returning * into device;
  elsif device.token_hash<>hashed then
    raise exception 'Browser token changed. Sign out and sign in again';
  else
    update public.zoro_devices set last_seen=now() where id=device.id;
  end if;
  return jsonb_build_object('available',true,'enabled',required,'approved',device.status='approved','status',device.status,'id',device.id);
end; $$;
create or replace function public.zoro_list_devices() returns jsonb
language plpgsql security definer set search_path='' as $$
declare result jsonb;
begin
  if not public.kora_allowed() then raise exception 'Approved sign-in required'; end if;
  select jsonb_build_object('enabled',coalesce((select approval_required from public.zoro_device_preferences where user_id=auth.uid()),false),
    'devices',coalesce(jsonb_agg(jsonb_build_object('id',id,'label',label,'location',reported_location,'status',status,'requested_at',requested_at,'last_seen',last_seen,'is_current',session_id=auth.jwt()->>'session_id') order by requested_at desc),'[]'::jsonb)) into result
  from public.zoro_devices where user_id=auth.uid() and requested_at>now()-interval '30 days';
  return result;
end; $$;
create or replace function public.zoro_set_device_approval(required boolean) returns void
language plpgsql security definer set search_path='' as $$
begin
  if not public.kora_allowed() or not exists(select 1 from public.zoro_devices where user_id=auth.uid() and session_id=auth.jwt()->>'session_id' and status='approved') then raise exception 'Approved sign-in required'; end if;
  insert into public.zoro_device_preferences values(auth.uid(),required)
  on conflict(user_id) do update set approval_required=excluded.approval_required;
end; $$;
create or replace function public.zoro_review_device(request_id uuid, approve boolean) returns void
language plpgsql security definer set search_path='' as $$
begin
  if not public.kora_allowed() then raise exception 'Approved sign-in required'; end if;
  update public.zoro_devices set status=case when approve then 'approved' else 'rejected' end
    where id=request_id and user_id=auth.uid() and status='pending' and requested_at>now()-interval '15 minutes';
  if not found then raise exception 'Request expired or unavailable'; end if;
end; $$;
create or replace function public.zoro_revoke_device(request_id uuid) returns void
language plpgsql security definer set search_path='' as $$
declare token text;
begin
  if not public.kora_allowed() then raise exception 'Approved sign-in required'; end if;
  select token_hash into token from public.zoro_devices where id=request_id and user_id=auth.uid() and session_id<>auth.jwt()->>'session_id';
  if token is null then raise exception 'Cannot revoke this browser here'; end if;
  if exists(select 1 from public.zoro_devices where user_id=auth.uid() and token_hash=token and session_id=auth.jwt()->>'session_id') then raise exception 'Use sign out to revoke this browser'; end if;
  update public.zoro_devices set status='rejected' where user_id=auth.uid() and token_hash=token;
end; $$;
revoke all on function public.zoro_base_allowed(),public.zoro_device_gate(text,text,text),public.zoro_list_devices(),public.zoro_set_device_approval(boolean),public.zoro_review_device(uuid,boolean),public.zoro_revoke_device(uuid) from public,anon;
grant execute on function public.zoro_base_allowed(),public.zoro_device_gate(text,text,text),public.zoro_list_devices(),public.zoro_set_device_approval(boolean),public.zoro_review_device(uuid,boolean),public.zoro_revoke_device(uuid) to authenticated;
commit;

-- SECTION: recovery-codes.sql
begin;
create table if not exists kora_private.recovery_codes (
  user_id uuid not null references auth.users(id) on delete cascade,
  code_hash text not null, primary key(user_id,code_hash)
);
create table if not exists kora_private.recovery_limits (
  user_id uuid primary key references auth.users(id) on delete cascade,
  failures integer not null default 0, blocked_until timestamptz
);
revoke all on kora_private.recovery_codes,kora_private.recovery_limits from public,anon,authenticated;
create or replace function public.zoro_generate_recovery_codes() returns setof text
language plpgsql security definer set search_path='' as $$
declare code text;
begin
  if not public.kora_allowed() then raise exception 'Approved authenticator sign-in required'; end if;
  delete from kora_private.recovery_codes where user_id=auth.uid();
  delete from kora_private.recovery_limits where user_id=auth.uid();
  for i in 1..8 loop
    code:=replace(gen_random_uuid()::text,'-','');
    insert into kora_private.recovery_codes values(auth.uid(),encode(sha256(convert_to(code,'UTF8')),'hex'));
    return next code;
  end loop;
end; $$;
-- Only the recovery Edge Function's server credential may call these functions.
create or replace function public.zoro_consume_recovery_code(actor uuid, recovery_code text) returns boolean
language plpgsql security definer set search_path='' as $$
declare limiter kora_private.recovery_limits;
begin
  if actor is null or not exists(select 1 from auth.users where id=actor) then return false; end if;
  perform pg_advisory_xact_lock(hashtextextended(actor::text,10));
  insert into kora_private.recovery_limits(user_id)values(actor)on conflict do nothing;
  select * into limiter from kora_private.recovery_limits where user_id=actor for update;
  if limiter.blocked_until>now() then return false; end if;
  delete from kora_private.recovery_codes where user_id=actor and code_hash=encode(sha256(convert_to(lower(trim(recovery_code)),'UTF8')),'hex');
  if found then delete from kora_private.recovery_limits where user_id=actor; return true; end if;
  update kora_private.recovery_limits set failures=failures+1,blocked_until=case when (failures+1)%5=0 then now()+interval '1 hour' else null end where user_id=actor;
  return false;
end; $$;
create or replace function public.zoro_finish_account_recovery(actor uuid) returns void
language plpgsql security definer set search_path='' as $$
begin
  delete from public.zoro_device_preferences where user_id=actor;
  delete from public.zoro_devices where user_id=actor;
  delete from kora_private.recovery_codes where user_id=actor;
end; $$;
revoke all on function public.zoro_generate_recovery_codes(),public.zoro_consume_recovery_code(uuid,text),public.zoro_finish_account_recovery(uuid) from public,anon,authenticated;
grant execute on function public.zoro_generate_recovery_codes() to authenticated;
grant execute on function public.zoro_consume_recovery_code(uuid,text),public.zoro_finish_account_recovery(uuid) to service_role;
commit;
